<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="wo-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="wo-opbar"><button @click="emit('back')">←</button><strong>WORKSOUT</strong><div><button data-testid="shopping-open-service" @click="emit('open-service')">SUPPORT</button><button @click="emit('open-orders')">RELEASES</button><button @click="emit('open-cart')">BAG<span v-if="cartQuantity">({{ cartQuantity }})</span></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="wo-bag"><header><span>DROP BAG / SIZE REVIEW</span><h1>{{ l('发售前最后一次检查轮廓','One last silhouette check before release') }}</h1><div><b>{{ cartQuantity }}</b><small>PIECES / CURRENT DROP</small></div></header><div v-if="!cartItems.length" class="wo-empty">DROP BAG EMPTY</div><div v-else class="wo-bag-layout"><section><article v-for="(line,index) in cartItems" :key="line.productId"><span class="wo-shot"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>DROP {{ String(index+1).padStart(2,'0') }}</em></span><div><small>RELEASE PIECE / SIZE SNAPSHOT</small><strong>{{ productDisplayTitle(line.product) }}</strong><p>SIZE / M · QTY / {{ line.quantity }}</p><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><span>RELEASE SUMMARY</span><strong>{{ cartTotalLabel }}</strong><dl><div><dt>DROP</dt><dd>FRI / 21:00</dd></div><div><dt>SHIP</dt><dd>2–4 DAYS</dd></div></dl><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" /> GIFT DROP</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">MANUAL RECIPIENT</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">LOCK RELEASE ORDER</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="wo-releases"><header><div><span>RELEASE ARCHIVE</span><h1>{{ l('已购发售批次','Purchased release batches') }}</h1></div><button @click="emit('open-logistics')">SHIPPING MANIFEST →</button></header><article v-for="(order,index) in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><b>{{ String(index+1).padStart(2,'0') }}</b><div><small>{{ formatLogisticsDate(order.createdAt) }} / {{ orderStatusLabel(order.status) }}</small><h2>{{ order.items.map(x=>x.title).join(' / ') }}</h2><p>{{ order.itemCount }} PIECES · {{ formatOrderTotal(order) }}</p></div><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">OPEN RELEASE</button><button @click="emit('delete-order',order.id)">×</button></article><div v-if="!orders.length" class="wo-empty">NO RELEASES</div></section>
    <section v-else-if="pageKey==='logistics'" class="wo-manifest" data-testid="shopping-logistics-panel"><header><button @click="emit('open-orders')">← RELEASES</button><span>SHIPPING MANIFEST</span><h1>{{ l('批次、承运与目的地','Batch, carrier, destination') }}</h1></header><article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="wo-code">{{ row.order.id.slice(-6).toUpperCase() }}</div><div><small>{{ row.latestEvent?logisticsEventTypeLabel(row.latestEvent.type):'PACKING' }}</small><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><b :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</b><em v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ [row.latestEvent.carrierName,row.latestEvent.trackingCode].filter(Boolean).join(' / ') }}</em></div><button :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">DETAIL →</button></article><div v-if="!logisticsRows.length" class="wo-empty">NO SHIPPING MANIFESTS</div></section>
    <section v-else-if="selectedOrder" class="wo-detail" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><span>RELEASE ORDER</span><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="wo-detail-cover"><span>DROP / ORDER SNAPSHOT</span><h2>{{ selectedOrder.items.map(x=>x.title).join(' / ') }}</h2><div><b data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</b><small>{{ selectedOrder.itemCount }} PIECES</small></div></section><section class="wo-detail-items"><article v-for="(item,index) in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>{{ String(index+1).padStart(2,'0') }}</span><div><h3>{{ item.title }}</h3><p>QTY {{ item.quantity }} / SIZE SNAPSHOT RETAINED</p></div><strong>{{ formatOrderItemSubtotal(item) }}</strong></article></section><section class="wo-detail-timeline" data-testid="shopping-order-detail-timeline"><span>SHIP LOG</span><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><b>{{ logisticsEventTypeLabel(event.type) }}</b><p>{{ event.summary||event.title }}</p><time>{{ formatLogisticsDate(event.createdAt) }}</time></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO SHIP LOG</p></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COMPLETE</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE</button></footer></section>
  </main>
